const right=c?`<div class="dh"><div class="dt">${esc(c.name)}</div></div><div class="card"><label class="lb">Notas del deportista<textarea id="cnotes" style="min-height:80px" placeholder="Objetivos, contexto…">${esc(c.notes)}</textarea></label></div><h3>Fisioterapia</h3><div class="card"><div class="row" style="margin:0">${cs_(c).filter(x=>x.status!='Alta').map(x=>`<button class="chip ed" data-a="fgo" data-id="${x.id}">${esc(x.name)}</button>`).join('')||'<span class="mut">Sin lesiones activas</span>'}<button class="chip" data-a="fgo" data-id="">Abrir seguimiento</button></div></div><h3>Planes semanales (${cw(c).length})</h3><div class="row" style="margin-top:0"><button data-a="awc">Asignar mi semana actual</button></div>${cw(c).map((w,i)=>weekCard(w,i)).join('')||'<p class="mut" style="margin:0 4px">Sin planes semanales.</p>'}<h3>Rutinas asignadas (${c.plans.length})</h3>${c.plans.map(planCard).join('')||'<p class="mut" style="margin:0 4px">Sin rutinas asignadas. Asígnalas desde la pestaña Planificar.</p>'}<div class="row" style="margin-top:22px"><button class="danger" data-a="delc">${ic('trash',16)} Eliminar deportista</button></div>`:`<div class="card empty"><b>Aún no tienes deportistas</b><p class="mut">Añade tu primer deportista para asignarle rutinas y semanas y llevar su seguimiento.</p></div>`;
